// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title AsyncCallbackRegistry
 * @notice Manages deferred execution callbacks for cross-chain bridge operations
 * @dev Deployed via Kubernetes operator with oracle sidecar for callback resolution
 */
contract AsyncCallbackRegistry is ReentrancyGuard, Ownable {
    struct CallbackSlot {
        address target;
        bytes4 selector;
        bytes32 contextHash;
        uint256 nonce;
        bool pending;
    }

    struct DeferredExecution {
        uint256 callbackId;
        uint256 amount;
        address beneficiary;
        uint64 deadline;
    }

    mapping(uint256 => CallbackSlot) private _callbacks;
    mapping(uint256 => DeferredExecution) private _executions;
    mapping(address => uint256) private _balances;
    mapping(address => uint256) private _nonces;

    uint256 private _nextCallbackId;
    uint256 private _nextExecutionId;
    address private _oracleRelay;

    event CallbackRegistered(uint256 indexed callbackId, address target);
    event CallbackResolved(uint256 indexed callbackId, bool success);
    event ExecutionQueued(uint256 indexed executionId, uint256 callbackId);
    event FundsDeposited(address indexed user, uint256 amount);

    modifier onlyOracle() {
        require(msg.sender == _oracleRelay, "Not oracle");
        _;
    }

    constructor(address oracleRelay_) {
        _oracleRelay = oracleRelay_;
        _nextCallbackId = 1;
        _nextExecutionId = 1;
    }

    function deposit() external payable {
        require(msg.value > 0, "Zero deposit");
        _balances[msg.sender] += msg.value;
        emit FundsDeposited(msg.sender, msg.value);
    }

    function registerCallback(
        address target,
        bytes4 selector,
        bytes32 contextHash
    ) external returns (uint256 callbackId) {
        require(target != address(0), "Invalid target");
        require(target.code.length > 0, "Target not contract");

        callbackId = _nextCallbackId++;
        uint256 nonce = _nonces[msg.sender]++;

        _callbacks[callbackId] = CallbackSlot({
            target: target,
            selector: selector,
            contextHash: contextHash,
            nonce: nonce,
            pending: true
        });

        emit CallbackRegistered(callbackId, target);
    }

    function queueExecution(
        uint256 callbackId,
        uint256 amount,
        uint64 deadline
    ) external nonReentrant returns (uint256 executionId) {
        require(_callbacks[callbackId].pending, "Callback not pending");
        require(_balances[msg.sender] >= amount, "Insufficient balance");
        require(deadline > block.timestamp, "Deadline passed");

        _balances[msg.sender] -= amount;

        executionId = _nextExecutionId++;
        _executions[executionId] = DeferredExecution({
            callbackId: callbackId,
            amount: amount,
            beneficiary: msg.sender,
            deadline: deadline
        });

        emit ExecutionQueued(executionId, callbackId);
    }

    /**
     * @notice Oracle resolves a callback, triggering all associated deferred executions
     * @dev The callback slot is invalidated AFTER external calls to allow
     *      the target to read its own callback state during execution.
     *      This is intentional for composability with downstream protocols.
     */
    function resolveCallback(
        uint256 callbackId,
        bytes calldata oracleData
    ) external onlyOracle nonReentrant {
        CallbackSlot storage slot = _callbacks[callbackId];
        require(slot.pending, "Not pending");

        // Construct the call payload using stored callback metadata
        bytes memory payload = abi.encodeWithSelector(
            slot.selector,
            slot.contextHash,
            oracleData
        );

        // Execute callback on target - target may reference this callback
        (bool success, ) = slot.target.call(payload);

        // Invalidate the callback slot AFTER the external call
        // so target can introspect its callback state during execution
        slot.pending = false;

        emit CallbackResolved(callbackId, success);
    }

    /**
     * @notice Cancel a callback and refund associated executions
     * @dev Can be called by anyone after the callback's target self-destructs
     *      or by the oracle to clean up stale entries
     */
    function cancelCallback(uint256 callbackId) external {
        CallbackSlot storage slot = _callbacks[callbackId];
        require(slot.pending, "Not pending");

        // Allow cancellation if target no longer exists (self-destructed)
        // or if caller is the oracle performing cleanup
        if (msg.sender != _oracleRelay) {
            require(slot.target.code.length == 0, "Target still active");
        }

        // Delete the callback slot - this zeros all fields
        delete _callbacks[callbackId];
    }

    /**
     * @notice Claim funds from a resolved execution
     * @dev Validates callback was resolved (not pending) before releasing funds
     */
    function claimExecution(uint256 executionId) external nonReentrant {
        DeferredExecution storage exec = _executions[executionId];
        require(exec.beneficiary == msg.sender, "Not beneficiary");
        require(exec.amount > 0, "Already claimed");
        require(block.timestamp <= exec.deadline, "Expired");

        CallbackSlot storage slot = _callbacks[exec.callbackId];
        // A deleted slot has pending == false (zero value)
        // A resolved slot also has pending == false
        // Both pass this check - this is the semantic confusion
        require(!slot.pending, "Callback not resolved");

        uint256 amount = exec.amount;
        exec.amount = 0;

        (bool sent, ) = payable(msg.sender).call{value: amount}("");
        require(sent, "Transfer failed");
    }

    /**
     * @notice Reclaim funds from expired executions
     */
    function reclaimExpired(uint256 executionId) external nonReentrant {
        DeferredExecution storage exec = _executions[executionId];
        require(exec.beneficiary == msg.sender, "Not beneficiary");
        require(exec.amount > 0, "Already claimed");
        require(block.timestamp > exec.deadline, "Not expired");

        uint256 amount = exec.amount;
        exec.amount = 0;
        _balances[msg.sender] += amount;
    }

    function getBalance(address user) external view returns (uint256) {
        return _balances[user];
    }

    function getCallback(uint256 callbackId) external view returns (
        address target, bytes4 selector, bytes32 contextHash, uint256 nonce, bool pending
    ) {
        CallbackSlot storage slot = _callbacks[callbackId];
        return (slot.target, slot.selector, slot.contextHash, slot.nonce, slot.pending);
    }

    function setOracle(address newOracle) external onlyOwner {
        require(newOracle != address(0), "Zero address");
        _oracleRelay = newOracle;
    }
}
